int send_chars_to_vterm(uint32_t vtermno, const char* buf, int count) {
    int result = -EPIPE;

    if (!buf || count <= 0) {
        return -EINVAL;
    }

    if (early_char_output) {
        result = early_char_output(vtermno, buf, count);
        if (result >= 0) {
            return result;
        }
    }

    struct port* port = get_port_by_vtermno(vtermno);
    if (!port) {
        return -EPIPE;
    }

    struct scatter_gather_list sg_list;
    sg_list_init(&sg_list);

    if (sg_list_add(&sg_list, buf, count) < 0) {
        return -ENOMEM;
    }

    result = port_send(port, &sg_list);

    sg_list_free(&sg_list);

    return result;
}
